#!/usr/bin/env python3
"""Auditable A1/A2/A3 vs B1 runner; final decisions are ALWAYS generated by LLMs.

Researcher-side reference evaluation, diagnostics and aggregation never modify model output.
Technical failures (transport/context truncation) are deferred for re-running, not scored
as model failures. Machine-readable reports deliberately separate completion from accuracy.
"""
from pathlib import Path
from datetime import datetime, timezone
from collections import Counter, defaultdict
import argparse
import hashlib
import shutil
import json
import re
import sys

BASE = Path(__file__).resolve().parents[1]
ALLOWED = {'YES', 'NO', 'NEED_MORE_INFORMATION'}
STAGES = ('A1', 'A2', 'A3', 'B1')
TECHNICAL_FAILURES = {'OUTPUT_TRUNCATED', 'CONTEXT_PRESSURE_REVIEW', 'TRANSPORT_ERROR', 'CONFIGURATION_ERROR', 'METADATA_INCOMPLETE_REVIEW', 'THINKING_OUTPUT_COMPATIBILITY_REVIEW'}
# MODEL_DEGENERATE_REPETITION: the server aborted generation because the model fell into a repetition loop (Ollama: 'token repeat limit reached').
# It is the model's own failure to produce an answer, so it is counted as a pipeline completion cost, NOT excluded as a technical failure.
MODEL_FORMAT_FAILURES = {'MODEL_JSON_INVALID', 'MODEL_SCHEMA_INVALID', 'MODEL_DEGENERATE_REPETITION'}


def read(rel):
    return json.loads((BASE / rel).read_text(encoding='utf8'))


def write(path, contents):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(contents, encoding='utf8')


def canon(x):
    return json.dumps(x, ensure_ascii=False, indent=2)


def hash_(x):
    return hashlib.sha256(x.encode('utf8')).hexdigest()


def now():
    return datetime.now(timezone.utc).isoformat()


def relay(x):
    return x if isinstance(x, str) else canon(x)


def metadata(run):
    # Works even if a complete run folder has been moved outside the repository.
    return json.loads((Path(run) / 'run_metadata.json').read_text(encoding='utf8'))


def format_shared(m):
    evidence = '\n'.join(f"[{p['id']}] {p['html']}" for p in m['policy_passages'])
    return (f"\n\n=== POLICY_PASSAGES ===\n{evidence}"
            f"\n\n=== DECISION_QUESTION ===\n{m['decision_question']}"
            f"\n\n=== CUSTOMER_SCENARIO ===\n{m['customer_scenario']}\n")


def format_a2(m, a1):
    return ((BASE / 'prompts/A2_match.txt').read_text(encoding='utf8') + format_shared(m)
            + f"\n=== INTERMEDIATE_REPRESENTATION (actual A1 JSON, wrapper excluded if present) ===\n{relay(a1)}\n")


def format_a3(m, a1, a2):
    """Critical design invariant: A3 receives the ORIGINAL evidence as well as IR."""
    return ((BASE / 'prompts/A3_llm_decide.txt').read_text(encoding='utf8') + format_shared(m)
            + f"\n=== INTERMEDIATE_REPRESENTATION (actual A1 JSON, wrapper excluded if present) ===\n{relay(a1)}"
            + f"\n\n=== CONDITION_STATUSES (actual A2 JSON, wrapper excluded if present) ===\n{relay(a2)}\n")


def read_run_json(run, stage):
    return json.loads((Path(run) / f'{stage}_parsed.json').read_text(encoding='utf8'))


def read_run_raw(run, stage):
    return (Path(run) / f'{stage}_raw.txt').read_text(encoding='utf8')


def ast_refs(expr):
    """Validates only expression SHAPE. Unknown/unused IDs are diagnostics, not rejects."""
    if not isinstance(expr, dict):
        raise ValueError('eligibility_expression: expression node must be an object')
    if set(expr) == {'ref'} and isinstance(expr['ref'], str) and expr['ref']:
        return [expr['ref']]
    if set(expr) == {'op', 'arg'} and expr['op'] == 'NOT':
        return ast_refs(expr['arg'])
    if set(expr) == {'op', 'args'} and expr['op'] in ('ALL', 'ANY'):
        args = expr['args']
        if not isinstance(args, list) or not args:
            raise ValueError('eligibility_expression: ALL/ANY requires nonempty args list')
        result = []
        for child in args:
            result.extend(ast_refs(child))
        return result
    raise ValueError(f'eligibility_expression: invalid node {repr(expr)[:150]}')


def _string(obj, field, context, nonempty=False):
    value = obj.get(field)
    if not isinstance(value, str) or (nonempty and not value.strip()):
        raise ValueError(f'{context}: {field} must be {"nonempty " if nonempty else ""}string')
    return value


def _list(obj, field, context):
    value = obj.get(field)
    if not isinstance(value, list):
        raise ValueError(f'{context}: {field} must be list')
    return value


def _string_list(obj, field, context):
    values = _list(obj, field, context)
    if not all(isinstance(item, str) for item in values):
        raise ValueError(f'{context}: {field} must contain strings')
    return values


def _reject_duplicate_object_keys(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise ValueError(f'Duplicate JSON object key {key!r}; refusing ambiguous payload')
        obj[key] = value
    return obj


def parse_json_envelope(raw):
    """Parse a single JSON object after *audited*, non-semantic outer wrapping only.

    Accepted: whitespace; one complete leading <think>...</think> block;
    an exact allowlisted introductory phrase; one outer ```json / ``` fence.
    Never extract a JSON-looking substring from free-form text, never repair JSON
    punctuation, never infer absent keys, and never alter JSON object values.
    Returns (parsed_object, metadata, normalized_json_text).
    """
    if not isinstance(raw, str):
        raise TypeError('raw model response must be a text string')
    normalized = raw.strip()
    changes = []
    once = set()
    for _ in range(4):
        m = re.match(r'\A<think>[\s\S]*?</think>(?:\s*\n|\s*)', normalized)
        if m and 'leading_closed_think_tag' not in once:
            removed = m.group()
            changes.append({'operation': 'leading_closed_think_tag',
                            'removed_character_count': len(removed),
                            'removed_text_sha256': hash_(removed)})
            normalized = normalized[m.end():].strip()
            once.add('leading_closed_think_tag')
            continue
        m = re.match(r'\AHere is (?:the |your )?(?:requested )?JSON\s*:\s*',
                     normalized, flags=re.IGNORECASE)
        if m and 'allowlisted_intro' not in once:
            changes.append({'operation': 'allowlisted_intro', 'removed_text': m.group()})
            normalized = normalized[m.end():].strip()
            once.add('allowlisted_intro')
            continue
        m = re.fullmatch(r'```(?:json)?[ \t]*\r?\n(?P<body>[\s\S]*?)\r?\n```',
                         normalized, flags=re.IGNORECASE)
        if m and 'single_outer_markdown_fence' not in once:
            changes.append({'operation': 'single_outer_markdown_fence'})
            normalized = m.group('body').strip()
            once.add('single_outer_markdown_fence')
            continue
        break
    details = {'raw_sha256': hash_(raw), 'parsed_text_sha256': hash_(normalized),
               'outer_format_processed': bool(changes), 'envelope_operations': changes,
               'parser_policy': 'v5_allowed_outer_wrappers_only',
               'json_payload_content_modified': False}
    return json.loads(normalized, object_pairs_hook=_reject_duplicate_object_keys), details, normalized


def schema_validate(stage, obj):
    """Reject malformed JSON structures; preserve semantic errors as diagnostic FLAGS."""
    if not isinstance(obj, dict):
        raise ValueError(f'{stage}: top-level response must be a JSON object')
    if stage == 'A1':
        atoms = _list(obj, 'atoms', 'A1')
        if not atoms:
            raise ValueError('A1: atoms must be nonempty')
        ids = []
        for idx, atom in enumerate(atoms):
            context = f'A1.atoms[{idx}]'
            if not isinstance(atom, dict):
                raise ValueError(f'{context}: must be an object')
            ids.append(_string(atom, 'id', context, nonempty=True))
            _string(atom, 'proposition', context, nonempty=True)
            _string(atom, 'entity_scope', context, nonempty=True)
            _string_list(atom, 'source_ids', context)
        # Duplicate/unused IDs are semantic anomalies, diagnosed separately.
        ast_refs(obj.get('eligibility_expression'))
    elif stage == 'A2':
        statuses = _list(obj, 'statuses', 'A2')
        for idx, row in enumerate(statuses):
            context = f'A2.statuses[{idx}]'
            if not isinstance(row, dict):
                raise ValueError(f'{context}: must be an object')
            _string(row, 'id', context, nonempty=True)
            if row.get('status') not in {'TRUE', 'FALSE', 'UNKNOWN', 'CONFLICTING'}:
                raise ValueError(f'{context}: status must be TRUE/FALSE/UNKNOWN/CONFLICTING')
            _string(row, 'evidence_quote', context)
            _string(row, 'justification', context)
    elif stage in ('A3', 'B1'):
        if obj.get('decision') not in ALLOWED:
            raise ValueError(f'{stage}: decision must be YES/NO/NEED_MORE_INFORMATION')
        _string(obj, 'justification', stage)
        _string_list(obj, 'missing_facts', stage)
        _string_list(obj, 'supporting_policy_ids', stage)
        if stage == 'A3':
            _string_list(obj, 'decisive_condition_ids', 'A3')
            _string_list(obj, 'unresolved_condition_ids', 'A3')
            _list(obj, 'ir_discrepancies', 'A3')
        if 'conditional_branches' in obj:
            for idx, row in enumerate(_list(obj, 'conditional_branches', stage)):
                if not isinstance(row, dict) or row.get('possible_answer') not in ('YES', 'NO'):
                    raise ValueError(f'{stage}.conditional_branches[{idx}] invalid branch')
                _string(row, 'conditions_in_words', f'{stage}.conditional_branches[{idx}]')
    else:
        raise ValueError(f'Unknown stage: {stage}')


def _flag(code, detail, **additional):
    return {'code': code, 'detail': detail, **additional}


def diagnostic_flags(stage, obj, run, world):
    """Non-blocking diagnostics. Return flags, never mutate/correct the model output."""
    flags = []
    valid_sources = {x['id'] for x in read('data/policy_dev38_13.json')['passages']}
    if stage == 'A1':
        atoms = obj['atoms']
        ids = [row['id'] for row in atoms]
        referenced = set(ast_refs(obj['eligibility_expression']))
        for unused in sorted(set(ids) - referenced):
            flags.append(_flag('UNUSED_ATOM', f'A1 atom {unused} is defined but unused by eligibility_expression', atom_id=unused))
        for unknown in sorted(referenced - set(ids)):
            flags.append(_flag('UNDEFINED_AST_ATOM', f'Expression references unknown atom {unknown}', atom_id=unknown))
        for atom_id, n in Counter(ids).items():
            if n > 1:
                flags.append(_flag('DUPLICATE_ATOM_ID', f'{atom_id} appears {n} times', atom_id=atom_id))
        for atom in atoms:
            invalid = sorted(set(atom['source_ids']) - valid_sources)
            if invalid:
                flags.append(_flag('INVALID_POLICY_ID', f"A1 atom {atom['id']} cites non-policy IDs {invalid}", atom_id=atom['id'], bad_ids=invalid))
            if not atom['source_ids']:
                flags.append(_flag('MISSING_POLICY_CITATION', f"A1 atom {atom['id']} has no cited source", atom_id=atom['id']))
    elif stage == 'A2':
        scenario = read(f'model_inputs/{world}.json')['customer_scenario']
        a1 = read_run_json(run, 'A1')
        expected = [x['id'] for x in a1['atoms']]
        observed = [x['id'] for x in obj['statuses']]
        for missing in sorted(set(expected) - set(observed)):
            flags.append(_flag('MISSING_STATUS_ID', f'A2 omitted atom ID {missing}', atom_id=missing))
        for extra in sorted(set(observed) - set(expected)):
            flags.append(_flag('EXTRA_STATUS_ID', f'A2 added unknown atom ID {extra}', atom_id=extra))
        for duplicated, n in Counter(observed).items():
            if n > 1:
                flags.append(_flag('DUPLICATE_STATUS_ID', f'A2 ID {duplicated} appears {n} times', atom_id=duplicated))
        for row in obj['statuses']:
            quote = row['evidence_quote']
            is_verbatim = (quote in scenario) if quote else None
            # Nonempty quotes must appear verbatim in the actual scenario; record both outcomes.
            if quote and not is_verbatim:
                flags.append(_flag('QUOTE_NOT_VERBATIM', f"A2 {row['id']} quote not found as exact scenario substring", atom_id=row['id'], quote_is_verbatim=False))
            if row['status'] in ('TRUE', 'FALSE') and not quote.strip():
                flags.append(_flag('ASSERTED_STATUS_WITHOUT_QUOTE', f"A2 {row['id']} is {row['status']} but evidence_quote is empty", atom_id=row['id']))
            if row['status'] == 'UNKNOWN' and quote.strip():
                flags.append(_flag('UNKNOWN_WITH_QUOTE', f"A2 {row['id']} UNKNOWN with nonempty evidence_quote (review whether quote supports uncertainty)", atom_id=row['id']))
    elif stage in ('A3', 'B1'):
        invalid = sorted(set(obj['supporting_policy_ids']) - valid_sources)
        if invalid:
            flags.append(_flag('INVALID_POLICY_ID', f'{stage} cites unknown policy IDs {invalid}', bad_ids=invalid))
        decision = obj['decision']
        missing = obj['missing_facts']
        if decision == 'NEED_MORE_INFORMATION' and not missing:
            flags.append(_flag('NEI_WITH_NO_MISSING_FACTS', f'{stage} requests information but names no missing_facts'))
        branches = obj.get('conditional_branches') or []
        if decision == 'NEED_MORE_INFORMATION' and not branches:
            flags.append(_flag('NEI_WITHOUT_CONDITIONAL_BRANCHES', f'{stage} requests information but gives no conditional_branches (the prompt asks for them when unresolved)'))
        if decision in ('YES', 'NO') and branches:
            flags.append(_flag('DECIDED_WITH_CONDITIONAL_BRANCHES', f'{stage} returned {decision} but still gives conditional_branches (prompt: empty when decided)'))
        if decision in ('YES', 'NO') and missing:
            flags.append(_flag('DECIDED_WITH_MISSING_FACTS', f'{stage} returned {decision} but still lists missing_facts'))
        if stage == 'A3':
            ids = {x['id'] for x in read_run_json(run, 'A1')['atoms']}
            for field in ('decisive_condition_ids', 'unresolved_condition_ids'):
                invalid_atom_ids = sorted(set(obj[field]) - ids)
                if invalid_atom_ids:
                    flags.append(_flag('INVALID_IR_ATOM_ID', f'A3 {field} references absent IR IDs {invalid_atom_ids}', bad_ids=invalid_atom_ids))
            unresolved = obj['unresolved_condition_ids']
            if decision in ('YES', 'NO') and unresolved:
                flags.append(_flag('DECIDED_WITH_UNRESOLVED_ATOMS', f'A3 returned {decision} while listing unresolved atoms', unresolved=unresolved))
            if decision == 'NEED_MORE_INFORMATION' and not unresolved:
                flags.append(_flag('NEI_WITHOUT_UNRESOLVED_ATOMS', 'A3 requested information but unresolved_condition_ids is empty; review original-source repair possibility'))
    return flags


def _prompt_hash_meta(run, stage, prompt):
    meta = metadata(run)
    meta.setdefault('prompts', {})[f'{stage}_sha256'] = hash_(prompt)
    write(Path(run) / 'run_metadata.json', canon(meta) + '\n')


def prepare(args):
    if not re.fullmatch(r'[A-Za-z0-9._-]+', args.run_id):
        raise ValueError('run-id may contain only A-Z/a-z/0-9/._-')
    source = read(f'model_inputs/{args.world}.json')
    run = BASE / 'runs' / args.run_id / args.world
    if run.exists():
        raise RuntimeError(f'Refusing to overwrite existing run: {run}')
    run.mkdir(parents=True)
    a1 = (BASE / 'prompts/A1_extract.txt').read_text(encoding='utf8') + format_shared(source)
    b1 = (BASE / 'prompts/B1_direct.txt').read_text(encoding='utf8') + format_shared(source)
    write(run / 'A1_PROMPT.txt', a1)
    write(run / 'B1_PROMPT.txt', b1)
    template_hashes = {f'{p.stem}_sha256': hash_(p.read_text(encoding='utf8')) for p in sorted((BASE / 'prompts').glob('*.txt'))}
    meta = {'world': args.world, 'run_id': args.run_id, 'model': args.model,
            'model_version': args.model_version or 'UNVERIFIED',
            'inference_settings': args.settings or 'NOT_RECORDED', 'date_utc': now(),
            'prompts': {'A1_sha256': hash_(a1), 'B1_sha256': hash_(b1)},
            'prompt_template_hashes': template_hashes, 'status': 'PREPARED; NO LLM CALLED'}
    write(run / 'run_metadata.json', canon(meta) + '\n')
    print(f'RUN DIRECTORY: {run}\nRun A1 and B1 in separate fresh chats; save their unchanged raw responses.')
    return run


def _stage_record_path(run, stage):
    return Path(run) / f'{stage}_record.json'


def _write_stage_event(run, stage, *, status, reason=None, detail=None, raw=None, api=None):
    """Record an external failure, including technical failures requiring a NEW run ID."""
    run = Path(run)
    dest = _stage_record_path(run, stage)
    if dest.exists() or (run / f'{stage}_parsed.json').exists():
        raise RuntimeError(f'{stage} already recorded; use a new run ID for a re-run')
    if stage not in STAGES:
        raise ValueError('invalid stage')
    if not (run / 'run_metadata.json').exists():
        raise FileNotFoundError('run_metadata.json not found')
    if raw is not None:
        write(run / f'{stage}_raw.txt', raw)
    event = {'stage': stage, 'saved_at_utc': now(), 'status': status,
             'reason': reason, 'detail': detail, 'raw_sha256': hash_(raw) if raw is not None else None,
             'valid_json': False, 'retry_required': reason in TECHNICAL_FAILURES,
             'api_metrics': api, 'diagnostic_flags': []}
    write(dest, canon(event) + '\n')
    return event


def report_failure(args):
    run = Path(args.run).expanduser().resolve()
    raw = Path(args.response).read_text(encoding='utf8') if args.response else None
    reason = args.reason
    status = 'technical_failure' if reason in TECHNICAL_FAILURES else 'model_format_failure'
    event = _write_stage_event(run, args.stage, status=status, reason=reason,
                               detail=args.detail or 'No further details provided', raw=raw)
    print(f'Recorded {args.stage}: {event["reason"]}; retry_required={event["retry_required"]}')


def record(args):
    run = Path(args.run).expanduser().resolve()
    if not (run / 'run_metadata.json').exists():
        raise FileNotFoundError('run_metadata.json not found')
    stage = args.stage
    if stage not in STAGES:
        raise ValueError('invalid stage')
    if _stage_record_path(run, stage).exists() or (run / f'{stage}_raw.txt').exists():
        raise RuntimeError('Refusing to overwrite previous response; create a new run for a retry')
    original = Path(args.response).expanduser().read_text(encoding='utf8')
    write(run / f'{stage}_raw.txt', original)
    event = {'stage': stage, 'saved_at_utc': now(), 'status': 'model_format_failure',
             'reason': None, 'raw_sha256': hash_(original), 'valid_json': False,
             'validation_error': None, 'retry_required': False, 'diagnostic_flags': []}
    if stage in ('A2', 'A3') and not (run / 'A1_parsed.json').exists():
        event['reason'] = 'DEPENDENCY_MISSING'
        event['validation_error'] = f'{stage} requires a recorded valid A1 output'
    elif stage == 'A3' and not (run / 'A2_parsed.json').exists():
        event['reason'] = 'DEPENDENCY_MISSING'
        event['validation_error'] = 'A3 requires a recorded valid A2 output'
    else:
        try:
            obj, unwrap_info, normalized = parse_json_envelope(original)
        except json.JSONDecodeError as exc:
            event['reason'] = 'MODEL_JSON_INVALID'
            event['validation_error'] = f'Invalid JSON at line {exc.lineno}, column {exc.colno}: {exc.msg}'
            event['json_envelope'] = {'parse_failed': True, 'original_raw_sha256': hash_(original),
                                      'raw_contains_think_tag': '<think>' in original,
                                      'raw_contains_fence': '```' in original}
        except ValueError as exc:
            event['reason'] = 'MODEL_JSON_INVALID'
            event['validation_error'] = str(exc)
            event['json_envelope'] = {'parse_failed': True, 'original_raw_sha256': hash_(original),
                                      'duplicate_key_or_invalid_payload': True}
        else:
            event['json_envelope'] = unwrap_info
            if unwrap_info['outer_format_processed']:
                # Preserve exact original separately. Parsed payload has identical JSON values.
                write(run / f'{stage}_outer_wrapper_removed_for_parsing.txt', normalized)
            try:
                schema_validate(stage, obj)
            except ValueError as exc:
                event['reason'] = 'MODEL_SCHEMA_INVALID'
                event['validation_error'] = str(exc)
            else:
                event['status'] = 'parsed'
                event['valid_json'] = True
                event['diagnostic_flags'] = diagnostic_flags(stage, obj, run, metadata(run)['world'])
                if stage == 'A2':
                    original_scenario = read(f'model_inputs/{metadata(run)["world"]}.json')['customer_scenario']
                    event['quote_verbatim_checks'] = [
                        {'atom_id': row['id'], 'quote_is_verbatim': row['evidence_quote'] in original_scenario
                            if row['evidence_quote'] else None, 'has_quote': bool(row['evidence_quote'])}
                        for row in obj['statuses']]
                write(run / f'{stage}_parsed.json', canon(obj) + '\n')
    write(_stage_record_path(run, stage), canon(event) + '\n')
    if not event['valid_json']:
        print(f'RAW SAVED, not parsed: {event["reason"]}: {event["validation_error"]}')
        return
    m = read(f'model_inputs/{metadata(run)["world"]}.json')
    if stage == 'A1':
        next_prompt = format_a2(m, read_run_json(run, 'A1'))
        write(run / 'A2_PROMPT.txt', next_prompt)
        _prompt_hash_meta(run, 'A2', next_prompt)
    elif stage == 'A2':
        next_prompt = format_a3(m, read_run_json(run, 'A1'), read_run_json(run, 'A2'))
        write(run / 'A3_PROMPT.txt', next_prompt)
        _prompt_hash_meta(run, 'A3', next_prompt)
    print(f'{stage} saved; semantic flags={len(event["diagnostic_flags"])}; raw reply unchanged.')


def eval_ref(expr, states):
    """Researcher-side Gold-only Boolean checker; NEVER used for A3/B1."""
    if 'ref' in expr:
        return states[expr['ref']]
    if expr['op'] == 'NOT':
        val = eval_ref(expr['arg'], states)
        return {'TRUE': 'FALSE', 'FALSE': 'TRUE', 'UNKNOWN': 'UNKNOWN', 'CONFLICTING': 'UNKNOWN'}[val]
    values = [eval_ref(child, states) for child in expr['args']]
    if expr['op'] == 'ALL':
        return 'FALSE' if 'FALSE' in values else 'TRUE' if all(x == 'TRUE' for x in values) else 'UNKNOWN'
    if expr['op'] == 'ANY':
        return 'TRUE' if 'TRUE' in values else 'FALSE' if all(x == 'FALSE' for x in values) else 'UNKNOWN'
    raise ValueError('unsupported operator')


def check(args=None):
    """Checks schema and data integrity only, NOT independent Gold truth."""
    policy = read('data/policy_dev38_13.json')
    worlds = read('data/scenarios_R0_R4.json')
    ref = read('gold/reference_conditions_and_logic.json')
    gold = read('gold/gold_per_run.json')['scenario_statuses']
    expected_worlds = {'R0','R1_L','R1_H','R2_L','R2_H','R3_L','R3_H'}
    assert [p['id'] for p in policy['passages']] == [f'E{i:02d}' for i in range(1,14)]
    assert {x['id'] for x in worlds['worlds']} == expected_worlds
    assert set(gold) == expected_worlds - {'R0'}
    ids = {a['id'] for a in ref['atoms']}
    assert ids == {'G_C1','G_C2','G_C3','G_X1','G_X2','G_X3','G_X4','G_X5'}
    assert set(ast_refs(ref['reference_logic'])) == ids
    for row in worlds['worlds']:
        world = row['id']
        m = read(f'model_inputs/{world}.json')
        assert m['policy_passages'] == policy['passages']
        assert m['customer_scenario'] == row['model_scenario']
        assert m['decision_question'] == row['decision_question']
        if world == 'R0':
            assert row['additional_information'] == ''
            continue
        states = gold[world]['statuses']
        assert set(states) == ids
        computed = {'TRUE':'YES','FALSE':'NO','UNKNOWN':'NEED_MORE_INFORMATION'}[eval_ref(ref['reference_logic'], states)]
        assert computed == gold[world]['reference_decision'] == row['decision_class']
        print(f'{world}: internal Gold consistency OK; reference={computed}')
    for prefix in ('R1','R2','R3'):
        assert gold[prefix+'_L']['statuses'] == gold[prefix+'_H']['statuses']
    for rel in ('A1_extract.txt', 'A2_match.txt', 'A3_llm_decide.txt', 'B1_direct.txt'):
        prompt = (BASE / 'prompts' / rel).read_text(encoding='utf8').lower()
        assert not any(x in prompt for x in ('gift aid', 'gift_aid', 'dev-38', 'elaine', 'robyn', 'devon', 'omar')), rel
    print('PASS: file/logic consistency ONLY; researcher Gold not independently validated.')

def _stage_state(run, stage):
    path = _stage_record_path(run, stage)
    if not path.exists():
        return {'stage': stage, 'status': 'not_run', 'reason': 'NOT_RUN', 'has_parsed': False}
    record = json.loads(path.read_text(encoding='utf8'))
    parsed = (Path(run) / f'{stage}_parsed.json').exists() and bool(record.get('valid_json'))
    status = 'parsed' if parsed else record.get('status', 'model_format_failure')
    reason = None if parsed else record.get('reason') or 'MODEL_SCHEMA_INVALID'
    return {'stage': stage, 'status': status, 'reason': reason, 'has_parsed': parsed,
            'diagnostic_flags': record.get('diagnostic_flags', []),
            'record_file': path.name, 'retry_required': reason in TECHNICAL_FAILURES,
            'api_metrics': record.get('api_metrics'),
            'json_envelope': record.get('json_envelope', {})}


RETRY_SEED_STEP = 1000


def retry_seed(base, k):
    """Attempt 1 uses the approved base seed; attempt k uses base + 1000*(k-1). Fixed in advance, recorded in every run. None stays None (APIs without a seed)."""
    return base if base is None or k == 1 else base + RETRY_SEED_STEP * (k - 1)


def archive_attempt(run, stage, k):
    """Keep a failed attempt's every file (prompt excepted) under attempts/<stage>_attemptNN/ so the next attempt starts clean. Nothing is deleted."""
    run = Path(run)
    dest = run / 'attempts' / f'{stage}_attempt{k:02d}'
    dest.mkdir(parents=True, exist_ok=False)
    for f in sorted(run.glob(f'{stage}_*')):
        if f.name in (f'{stage}_PROMPT.txt', f'{stage}_stage_attempts.json'):
            continue
        shutil.move(str(f), str(dest / f.name))
    return dest


def run_with_retries(run, stage, attempt_fn, max_attempts, base_seed):
    """Re-sample ONE stage after a MODEL format failure (invalid JSON, wrong schema, repetition abort) with the SAME frozen prompt and a new seed.
    No error text is fed back and no output is edited. Technical failures are never retried here (they need a new run ID, as before).
    After max_attempts failures the stage stays failed and counts as UNFINISHED. attempt_fn(seed) -> True if a valid output was recorded."""
    run = Path(run)
    attempts = []
    for k in range(1, max(1, int(max_attempts)) + 1):
        seed = retry_seed(base_seed, k)
        ok = bool(attempt_fn(seed))
        st = _stage_state(run, stage)
        entry = {'attempt': k, 'seed': seed, 'valid': ok, 'status': st['status'], 'reason': None if ok else st['reason']}
        attempts.append(entry)
        if ok:
            break
        if st['reason'] not in MODEL_FORMAT_FAILURES:
            entry['not_retried'] = 'not a model format failure (technical or dependency problem)'
            break
        if k < max_attempts:
            archive_attempt(run, stage, k)
    last = attempts[-1]
    summary = {'stage': stage, 'max_attempts': int(max_attempts), 'attempts': attempts, 'valid': last['valid'],
               'first_attempt_valid': attempts[0]['valid'],
               'unfinished_after_retries': (not last['valid']) and last['reason'] in MODEL_FORMAT_FAILURES and len(attempts) == int(max_attempts),
               'retry_rule': f'same frozen prompt, no error feedback, seed = base + {RETRY_SEED_STEP}*(attempt-1); the first valid output is the one used'}
    write(run / f'{stage}_stage_attempts.json', canon(summary) + '\n')
    return last['valid']


def stage_attempt_summary(run, stage):
    f = Path(run) / f'{stage}_stage_attempts.json'
    return json.loads(f.read_text(encoding='utf8')) if f.exists() else None


def _metric_files(run, stage):
    run = Path(run)
    dirs = [run] + sorted((run / 'attempts').glob(f'{stage}_attempt*')) if (run / 'attempts').exists() else [run]
    out = []
    for d in dirs:
        for name in (f'{stage}_ollama_metrics.json', f'{stage}_api_metrics.json'):
            if (d / name).exists():
                out.append((d / name))
    return out


def stage_usage(run, stage):
    """Observed token counts summed over EVERY model call of this stage (retries included), from the runner's own metrics files; never estimated.
    A call that produced no metrics (e.g. a server abort) makes the stage 'incomplete' instead of being guessed."""
    files = _metric_files(run, stage)
    summ = stage_attempt_summary(run, stage)
    calls = len(summ['attempts']) if summ else len(files)
    if not files and not calls:
        return {'called': False, 'prompt': None, 'generated': None, 'attempts': 0, 'calls': 0, 'complete': False}
    prompt = generated = 0; http_attempts = 0; complete = len(files) == calls and bool(files)
    for f in files:
        m = json.loads(f.read_text(encoding='utf8'))
        if f.name.endswith('_ollama_metrics.json'):
            p, g, a = m.get('prompt_eval_count'), m.get('eval_count'), 1
        else:
            u = m.get('usage') or {}
            p, g, a = u.get('input_tokens', u.get('prompt_tokens')), u.get('output_tokens', u.get('completion_tokens')), m.get('attempts', 1)
        http_attempts += a
        if isinstance(p, int) and isinstance(g, int):
            prompt += p; generated += g
        else:
            complete = False
    return {'called': True, 'prompt': prompt if complete else None, 'generated': generated if complete else None,
            'attempts': http_attempts, 'calls': calls, 'complete': complete}


def path_usage(run, stages):
    rows = [stage_usage(run, s) for s in stages]
    called = [r for r in rows if r['called']]
    complete = bool(called) and all(r['complete'] for r in called)
    return {'calls': sum(r['calls'] for r in called), 'prompt_tokens': sum(r['prompt'] for r in called) if complete else None,
            'generated_tokens': sum(r['generated'] for r in called) if complete else None, 'usage_complete': complete,
            'note': 'Model calls and token counts as reported by the server, summed over all attempts of all stages (retries included); API-level HTTP retries are counted in attempts.',
            'attempts': sum(r['attempts'] for r in called)}


def path_attempts(run, stages):
    """Per-stage number of model attempts and whether every stage of the path was valid on its FIRST attempt."""
    per, first_ok, unfinished = {}, True, None
    for s in stages:
        summ = stage_attempt_summary(run, s)
        st = _stage_state(run, s)
        if summ:
            per[s] = len(summ['attempts']); ok1 = summ['first_attempt_valid']
            if summ['unfinished_after_retries'] and unfinished is None:
                unfinished = s
        elif st['status'] == 'not_run':
            per[s] = 0; ok1 = False
        else:
            per[s] = 1; ok1 = st['has_parsed']
        first_ok = first_ok and ok1
    return {'per_stage': per, 'total_model_calls': sum(per.values()), 'retry_calls': sum(max(0, n - 1) for n in per.values()), 'first_attempt_all_valid': first_ok, 'unfinished_stage': unfinished}


def _path_result(run, path_name, gold_label):
    stages = ('A1', 'A2', 'A3') if path_name == 'A' else ('B1',)
    result = _path_result_core(run, path_name, gold_label, stages)
    result['usage'] = path_usage(run, stages)
    result['attempts'] = path_attempts(run, stages)
    return result


def _path_result_core(run, path_name, gold_label, stages):
    for stage in stages:
        st = _stage_state(run, stage)
        if not st['has_parsed']:
            reason = st['reason']
            if reason in TECHNICAL_FAILURES:
                cost = 'technical_deferred'
            elif reason in MODEL_FORMAT_FAILURES:
                cost = 'model_format_failure'
            elif reason == 'NOT_RUN':
                cost = 'not_run'
            else:
                cost = 'other_incomplete'
            return {'status': 'no_conclusion', 'decision': None, 'correct': None,
                    'stop_stage': stage, 'reason': reason, 'completion_category': cost,
                    'retry_required': reason in TECHNICAL_FAILURES,
                    'diagnostic_flags': st.get('diagnostic_flags', [])}
    final = 'A3' if path_name == 'A' else 'B1'
    obj = read_run_json(run, final)
    all_flags = [{'stage': stage, **flag} for stage in stages
                 for flag in _stage_state(run, stage).get('diagnostic_flags', [])]
    return {'status': 'concluded', 'decision': obj['decision'],
            'correct': obj['decision'] == gold_label if gold_label is not None else None, 'stop_stage': None,
            'reason': None, 'completion_category': 'completed', 'retry_required': False,
            'diagnostic_flags': all_flags}


def r0_semantic_review_template(run):
    """Provide an explicit, editable R0 native Gold condition-alignment worksheet.

    Gold text comes from the original official record; reviewer decisions are BLANK.
    Never auto-label semantic correctness based on mere policy ID overlap.
    """
    native = read('data/official_dev38_record_fields.json')
    a1_ids = ([atom['id'] for atom in read_run_json(run, 'A1')['atoms']]
              if _stage_state(run, 'A1')['has_parsed'] else [])
    rows = []
    for answer, conditions in native['answers']:
        for index, condition in enumerate(conditions, start=1):
            rows.append({'gold_condition_id': f'{answer.upper()}_{index}',
                         'gold_answer_branch': answer.upper(),
                         'official_gold_condition': condition,
                         'matched_A1_atom_ids': [],
                         'semantic_match': None,
                         'review_notes': ''})
    return {'instructions': 'Manual review. Map each official Gold condition to zero or more model-generated A1 atom IDs. Set semantic_match true or false after checking exact meaning; do not score by source ID alone. Do not modify Gold text.',
            'reviewer': '', 'review_timestamp': '',
            'available_A1_atom_ids': a1_ids, 'items': rows}


def semantic_review_result(run):
    """Optional reviewed, not automated, semantic matching against original native Gold."""
    destination = Path(run) / 'R0_NATIVE_SEMANTIC_REVIEW.json'
    template_path = Path(run) / 'R0_NATIVE_SEMANTIC_REVIEW_TEMPLATE.json'
    if not template_path.exists():
        write(template_path, canon(r0_semantic_review_template(run)) + '\n')
    if not destination.exists():
        return {'status': 'PENDING_MANUAL_REVIEW', 'template': template_path.name,
                'note': 'Native 3+5 conditions have NOT been semantically scored; citation counts are only proxies.'}
    data = json.loads(destination.read_text(encoding='utf8'))
    reference = r0_semantic_review_template(run)
    expected = {x['gold_condition_id']: x['official_gold_condition'] for x in reference['items']}
    seen = {}
    for item in data.get('items', []):
        key = item.get('gold_condition_id')
        if key not in expected or key in seen or item.get('official_gold_condition') != expected.get(key):
            return {'status': 'INVALID_REVIEW', 'note': f'Missing/duplicated/changed Gold condition {key!r}'}
        if item.get('semantic_match') not in (True, False):
            return {'status': 'INCOMPLETE_REVIEW', 'note': f'Condition {key} semantic_match is not a boolean'}
        mapped = item.get('matched_A1_atom_ids')
        if not isinstance(mapped, list) or any(x not in reference['available_A1_atom_ids'] for x in mapped):
            return {'status': 'INVALID_REVIEW', 'note': f'Condition {key} maps to an unknown A1 atom ID'}
        if item['semantic_match'] and not mapped:
            return {'status': 'INVALID_REVIEW', 'note': f'Condition {key} marked true but has no mapped model atoms'}
        seen[key] = item
    if set(seen) != set(expected) or not data.get('reviewer'):
        return {'status': 'INCOMPLETE_REVIEW', 'note': 'Reviewer name or some Gold conditions are missing'}
    count = sum(item['semantic_match'] for item in seen.values())
    return {'status': 'MANUALLY_REVIEWED', 'reviewer': data['reviewer'],
            'correct_condition_semantic_matches': count,
            'official_condition_count': len(expected),
            'manual_condition_recall': count / len(expected),
            'note': 'Manual review of official-condition recall only; not precision of model-added atoms.'}


def official_r0_check(run, paths):
    """Actual limited comparisons against OFFICIAL conditional answer Gold.

    Does not pretend lexical citation coverage = semantic condition correctness.
    """
    native = read('data/official_dev38_record_fields.json')
    policy = read('data/policy_dev38_13.json')['passages']
    text_to_id = {p['html']: p['id'] for p in policy}
    gold = [{'answer': answer.upper(), 'condition_source_ids': [text_to_id.get(text) for text in snippets]}
            for answer, snippets in native['answers']]
    known_ids = {ref for row in gold for ref in row['condition_source_ids'] if ref}
    report = {'gold_answers': gold, 'reference_condition_count': sum(len(row[1]) for row in native['answers']),
              'source_lookup_all_found': all(v is not None for x in gold for v in x['condition_source_ids']),
              'warnings': ['Only source-ID coverage and YES/NO branch coverage can be checked mechanically.',
                           'Whether an atom semantically expresses a Gold condition requires manual independent alignment.',
                           'Native ConditionalQA Gold is NOT a decision-state Gold.']}
    if _stage_state(run, 'A1')['has_parsed']:
        a1 = read_run_json(run, 'A1')
        cited = set(x for atom in a1['atoms'] for x in atom['source_ids'])
        per = [{'gold_answer': gold_entry['answer'], 'gold_policy_id': source,
                'source_cited_by_A1': source in cited}
               for gold_entry in gold for source in gold_entry['condition_source_ids']]
        report['A1_native_gold_source_citation_proxy'] = {
            'items': per, 'covered': sum(x['source_cited_by_A1'] for x in per),
            'total': len(per), 'fraction': sum(x['source_cited_by_A1'] for x in per)/len(per) if per else None,
            'interpretation': 'CITATION-ONLY coverage; NOT condition semantic precision/recall'}
    else:
        report['A1_native_gold_source_citation_proxy'] = None
    for stage in ('A3', 'B1'):
        if _stage_state(run, stage)['has_parsed']:
            out = read_run_json(run, stage)
            observed = {b.get('possible_answer') for b in out.get('conditional_branches', []) if isinstance(b, dict)}
            if out['decision'] in ('YES','NO'):
                observed.add(out['decision'])
            expected = {x['answer'] for x in gold}
            report[stage+'_native_branch_label_coverage'] = {'gold_labels': sorted(expected),
                 'observed_labels': sorted(observed), 'missing_labels': sorted(expected - observed),
                 'recall': len(observed & expected)/len(expected),
                 'interpretation': 'Label-level branch coverage only; condition text needs manual semantic review'}
        else:
            report[stage+'_native_branch_label_coverage'] = None
    report['A1_native_gold_semantic_review'] = semantic_review_result(run)
    return report


def audit_run(run, save=True):
    run = Path(run).expanduser().resolve()
    meta = metadata(run)
    world = meta['world']
    gold = read('gold/gold_per_run.json')['scenario_statuses'].get(world)
    result = {'schema_version': '5.0', 'world': world, 'model': meta['model'],
              'model_version': meta.get('model_version'), 'run_id': meta.get('run_id'),
              'researcher_gold_decision': gold['reference_decision'] if gold else None,
              'stage_validation': {stage: _stage_state(run, stage) for stage in STAGES},
              'paths': {}, 'paired_quality_eligible': False,
              'limitations': ['R0 native conditional Gold is not the researcher decision-state Gold.',
                              'Warning flags are not automatic semantic correctness verdicts.',
                              'One base case with correlated scenario variants is not a generalizable accuracy estimate.']}
    result['paths']['A'] = _path_result(run, 'A', gold['reference_decision'] if gold else None)
    result['paths']['B'] = _path_result(run, 'B', gold['reference_decision'] if gold else None)
    a = result['paths']['A']
    b = result['paths']['B']
    if gold is not None and a['status'] == 'concluded' and b['status'] == 'concluded':
        result['paired_quality_eligible'] = True
        result['paired'] = {'A_correct': a['correct'], 'B_correct': b['correct'],
                            'both_correct': bool(a['correct'] and b['correct']),
                            'A_only_correct': bool(a['correct'] and not b['correct']),
                            'B_only_correct': bool(b['correct'] and not a['correct'])}
    else:
        result['paired'] = None
    if world == 'R0':
        result['official_conditionalqa_gold_comparison'] = official_r0_check(run, result['paths'])
    else:
        import stepwise_review
        result['stepwise_semantic_review'] = stepwise_review.review_status(run)
    if save:
        write(run / 'POST_RUN_GOLD_COMPARISON.json', canon(result) + '\n')
    return result


def audit(args):
    report = audit_run(args.run)
    print(f"Audited {args.run}: A={report['paths']['A']['status']} "
          f"[{report['paths']['A']['stop_stage'] or '-'} / {report['paths']['A']['reason'] or '-'}], "
          f"B={report['paths']['B']['status']} [{report['paths']['B']['reason'] or '-'}], "
          f"paired={report['paired_quality_eligible']}")


def _usage_stats(outcomes):
    """Cost of a path: model calls and observed tokens per attempted run, so A (3 calls) and B (1 call) can be compared on cost."""
    u = [x['usage'] for x in outcomes if x.get('usage') and x['usage']['calls']]
    full = [x for x in u if x['usage_complete']]
    return {'runs_with_calls': len(u), 'total_calls': sum(x['calls'] for x in u),
            'mean_calls_per_run': (sum(x['calls'] for x in u) / len(u)) if u else None,
            'runs_with_complete_token_counts': len(full),
            'mean_prompt_tokens_per_run': (sum(x['prompt_tokens'] for x in full) / len(full)) if full else None,
            'mean_generated_tokens_per_run': (sum(x['generated_tokens'] for x in full) / len(full)) if full else None,
            'mean_total_tokens_per_run': (sum(x['prompt_tokens'] + x['generated_tokens'] for x in full) / len(full)) if full else None,
            'includes_runs_that_stopped_early': True}


def _stats_for_path(outcomes):
    counts = Counter(x['completion_category'] for x in outcomes)
    completed = counts['completed']
    model_format = counts['model_format_failure']
    eligible = completed + model_format
    evaluated_answers = [x for x in outcomes if x['status'] == 'concluded' and x.get('correct') is not None]
    correct = sum(bool(x['correct']) for x in evaluated_answers)
    reason_counts = dict(Counter(x['reason'] for x in outcomes if x['reason']))
    stop_counts = dict(Counter(x['stop_stage'] for x in outcomes if x['stop_stage']))
    terminal_attempts = completed + model_format + counts['technical_deferred']
    return {'planned_or_prepared': len(outcomes), 'completed': completed,
            'model_format_failures': model_format,
            'technical_deferred': counts['technical_deferred'],
            'not_run': counts['not_run'], 'other_incomplete': counts['other_incomplete'],
            'evaluation_eligible': eligible,
            'completion_rate': completed/eligible if eligible else None,
            'operational_completion_rate_observed': completed/terminal_attempts if terminal_attempts else None,
            'terminal_attempts_including_technical': terminal_attempts,
            'stop_stage_counts': stop_counts, 'reason_counts': reason_counts,
            'answer_correct': correct, 'answer_evaluated': len(evaluated_answers),
            'answer_accuracy_conditional_on_conclusion': correct/len(evaluated_answers) if evaluated_answers else None,
            'repetition_loop_aborts': reason_counts.get('MODEL_DEGENERATE_REPETITION', 0),
            'repetition_loop_note': 'Counted as completion failures, but reported on their own line: the server aborts them, and whether they occur depends on the decoding configuration (format mode, schema) as well as on the model. Do not read them as reasoning failures of Pipeline A.',
            'first_attempt_all_valid': sum(1 for x in outcomes if x.get('attempts') and x['attempts']['first_attempt_all_valid']),
            'first_attempt_rate': (sum(1 for x in outcomes if x.get('attempts') and x['attempts']['first_attempt_all_valid']) / eligible) if eligible else None,
            'retry_calls_total': sum(x['attempts']['retry_calls'] for x in outcomes if x.get('attempts')),
            'unfinished_after_retries': model_format,
            'retry_note': 'With retries, a path is "completed" once every stage produced a valid output within the attempt cap; model_format_failures = UNFINISHED after the cap. first_attempt_rate = share valid at the first attempt of every stage (the single-shot reliability). Technical failures are not retried.',
            'usage': _usage_stats(outcomes),
            'note': 'Technical/transport failures and not-run attempts are excluded from evaluation denominator, retained in counts.'}


def settings_for_cohort(value):
    """Repetition seeds vary BY DESIGN; exclude seed but not thinking/ctx/temperature."""
    if not isinstance(value, str):
        return value
    try:
        cfg = json.loads(value)
    except (ValueError, TypeError):
        return value
    if isinstance(cfg, dict):
        cfg.pop('seed', None)
        if isinstance(cfg.get('options'), dict):
            cfg['options'].pop('seed', None)
    return cfg


def r0_official_block(r0_runs):
    """R0 = original ConditionalQA dev-38 scored against the OFFICIAL conditional answers (3 YES + 5 NO conditions).

    Reported on its own. Its decision output is NOT a YES/NO/NEED_MORE_INFORMATION accuracy against a researcher
    label, and semantic condition coverage exists only after the manual native-Gold review."""
    if not r0_runs:
        return None
    reviews = [x['official_conditionalqa_gold_comparison']['A1_native_gold_semantic_review'] for x in r0_runs]
    reviewed = [r for r in reviews if r.get('status') == 'MANUALLY_REVIEWED']
    proxy = [x['official_conditionalqa_gold_comparison'].get('A1_native_gold_source_citation_proxy') for x in r0_runs]
    proxy = [x for x in proxy if x]
    branch = {}
    for stage in ('A3', 'B1'):
        rows = [x['official_conditionalqa_gold_comparison'].get(stage + '_native_branch_label_coverage') for x in r0_runs]
        rows = [r for r in rows if r]
        branch[stage] = {'runs_with_output': len(rows), 'mean_label_recall': sum(r['recall'] for r in rows) / len(rows) if rows else None,
                         'interpretation': 'Label-level coverage of the official YES/NO branches only; not condition correctness.'}
    return {
        'runs': len(r0_runs),
        'path_A': _stats_for_path([x['paths']['A'] for x in r0_runs]),
        'path_B': _stats_for_path([x['paths']['B'] for x in r0_runs]),
        'native_semantic_review': {
            'manually_reviewed_runs': len(reviewed), 'pending_or_incomplete_runs': len(reviews) - len(reviewed),
            'pooled_official_condition_recall': (sum(r['correct_condition_semantic_matches'] for r in reviewed)
                                                 / sum(r['official_condition_count'] for r in reviewed)) if reviewed else None,
            'note': 'Official-condition recall of model A1 atoms, by human review only; model-added atoms are not scored.'},
        'A1_source_citation_proxy_mean': sum(x['fraction'] for x in proxy if x['fraction'] is not None) / len(proxy) if proxy else None,
        'A1_source_citation_proxy_note': 'CITATION-ONLY proxy. Do not present as condition accuracy.',
        'native_branch_label_coverage': branch,
        'reporting_rule': 'Present R0 in its own table. Never merge it with the R1-R3 YES/NO/NEED_MORE_INFORMATION accuracy.'}


def summarize_runs(runs_root=None):
    runs_root = Path(runs_root) if runs_root is not None else BASE / 'runs'
    run_dirs = sorted(runs_root.glob('*/*/run_metadata.json')) if runs_root.exists() else []
    reports = []
    for meta_file in run_dirs:
        run = meta_file.parent
        try:
            report = audit_run(run)
            meta = metadata(run)
            group_desc = {'model': meta['model'], 'model_version': meta.get('model_version'),
                          'inference_settings_except_repetition_seed': settings_for_cohort(meta.get('inference_settings')),
                          'prompt_template_hashes': meta.get('prompt_template_hashes')}
            cohort = hash_(canon(group_desc))[:12]
            reports.append({'run_dir': str(run), 'cohort': cohort, 'cohort_metadata': group_desc, 'audit': report})
        except Exception as exc:
            # Do not make corrupt run folders silently disappear from summaries.
            reports.append({'run_dir': str(run), 'cohort': 'READ_ERROR',
                            'error': f'{type(exc).__name__}: {exc}'})
    groups = defaultdict(list)
    for item in reports:
        groups[item['cohort']].append(item)
    summary = {'schema_version': '5.0', 'runs_found': len(run_dirs), 'cohorts': {},
               'definitions': {
                   'conclusion': 'A3 or B1 returns a structurally valid YES, NO or NEED_MORE_INFORMATION; semantic warnings remain visible.',
                   'completion_rate': 'completed/(completed + model JSON/schema failures). Transport/truncation/configuration and not-started attempts are pending or must be rerun, not model failures.',
                   'answer_accuracy': 'correct final decision / valid final decisions, on concluded attempts only; this does not fold model-format failures into wrong answers.',
                   'paired_accuracy': 'compare A and B ONLY when both have valid final decisions in the SAME run_id and world.',
                   'R0_vs_synthetic': 'R0 (official conditional answers) and R1-R3 (researcher decision labels) have different evaluation targets. Cohort path_A/path_B/paired_quality are synthetic-only; R0 is reported under R0_official.',
                   'stepwise_semantic_scores': 'A1 coverage, A2 semantic accuracy, missing-information matching and reasoning grounding are NOT computed here; see scripts/stepwise_review.py (human review).',
                   'unit_of_analysis': 'Repeated runs and R0 and the six synthetic variants share one base case. Do not treat them as independent policy examples.',
                   'accepted_output_wrappers': 'Allowed outer fences/intros/closed leading think tags are recorded and not counted as model-format failures; JSON contents never repaired.'}}
    for cohort, items in groups.items():
        good_all = [x['audit'] for x in items if 'audit' in x]
        # R0 (official ConditionalQA conditional answers) and R1-R3 (researcher decision labels) answer DIFFERENT
        # evaluation questions: they are never pooled. path_A / path_B / paired_quality below are synthetic only.
        good = [x for x in good_all if x['world'] != 'R0']
        r0_runs = [x for x in good_all if x['world'] == 'R0']
        a = [x['paths']['A'] for x in good]
        b = [x['paths']['B'] for x in good]
        paired = [x for x in good if x['paired_quality_eligible']]
        p_a_correct = sum(bool(x['paths']['A']['correct']) for x in paired)
        p_b_correct = sum(bool(x['paths']['B']['correct']) for x in paired)
        summary['cohorts'][cohort] = {
            'metadata': items[0].get('cohort_metadata'), 'runs': len(items),
            'scope_of_path_and_paired_statistics': 'SYNTHETIC R1_L..R3_H ONLY (YES / NO / NEED_MORE_INFORMATION against researcher labels). R0 is in R0_official.',
            'R0_official': r0_official_block(r0_runs),
            'unreadable_runs': [{'run_dir': x['run_dir'], 'error': x['error']} for x in items if 'error' in x],
            'path_A': _stats_for_path(a), 'path_B': _stats_for_path(b),
            'paired_quality': {'n': len(paired),
                               'A_correct': p_a_correct, 'B_correct': p_b_correct,
                               'A_accuracy': p_a_correct/len(paired) if paired else None,
                               'B_accuracy': p_b_correct/len(paired) if paired else None,
                               'A_only_correct': sum(x['paired']['A_only_correct'] for x in paired),
                               'B_only_correct': sum(x['paired']['B_only_correct'] for x in paired),
                               'both_correct': sum(x['paired']['both_correct'] for x in paired),
                               'neither_correct': sum(not (x['paths']['A']['correct'] or x['paths']['B']['correct']) for x in paired)},
            'by_world': {},
            'run_statuses': [{'run_id': x['run_id'], 'world': x['world'],
                              'A': {k:x['paths']['A'].get(k) for k in ('status','stop_stage','reason','completion_category','correct')},
                              'B': {k:x['paths']['B'].get(k) for k in ('status','stop_stage','reason','completion_category','correct')},
                              'paired': x['paired_quality_eligible']} for x in good],
            'outer_wrapper_normalizations': dict(Counter(
                action['operation']
                for x in good for stage in STAGES
                for action in x['stage_validation'][stage].get('json_envelope', {}).get('envelope_operations', [])
            ))}
        by_world = summary['cohorts'][cohort]['by_world']
        for world in sorted({r['world'] for r in good}):
            subset = [r for r in good if r['world'] == world]
            paired_world = [r for r in subset if r['paired_quality_eligible'] and r['world'] != 'R0']
            by_world[world] = {'path_A': _stats_for_path([r['paths']['A'] for r in subset]),
                               'path_B': _stats_for_path([r['paths']['B'] for r in subset]),
                               'paired_n': len(paired_world),
                               'paired_A_correct': sum(r['paths']['A']['correct'] for r in paired_world),
                               'paired_B_correct': sum(r['paths']['B']['correct'] for r in paired_world)}
    return summary


def summary_cmd(args):
    output = summarize_runs(args.runs_root)
    dest = Path(args.output) if args.output else BASE / 'reports' / 'SUMMARY.json'
    write(dest, canon(output) + '\n')
    print(f'Found {output["runs_found"]} run folders. Wrote {dest}')
    for cohort, info in output['cohorts'].items():
        a, b = info['path_A'], info['path_B']
        paired = info['paired_quality']
        print(f'{cohort} [SYNTHETIC R1-R3 ONLY]: A completion={a["completed"]}/{a["evaluation_eligible"]} '
              f'A answer accuracy={a["answer_correct"]}/{a["answer_evaluated"]}; '
              f'B completion={b["completed"]}/{b["evaluation_eligible"]} '
              f'B answer accuracy={b["answer_correct"]}/{b["answer_evaluated"]}; '
              f'PAIRED n={paired["n"]} A={paired["A_correct"]}/{paired["n"]} '
              f'B={paired["B_correct"]}/{paired["n"]}; '
              f'technical deferred A={a["technical_deferred"]}, B={b["technical_deferred"]}')
        r0 = info.get('R0_official')
        if r0:
            nr = r0['native_semantic_review']
            print(f'  [R0 OFFICIAL, reported separately] runs={r0["runs"]}; manual native-Gold review: '
                  f'{nr["manually_reviewed_runs"]} reviewed, {nr["pending_or_incomplete_runs"]} pending; '
                  f'official-condition recall={nr["pooled_official_condition_recall"]}')


def cli():
    ap = argparse.ArgumentParser(description=__doc__)
    sub = ap.add_subparsers(dest='cmd', required=True)
    p = sub.add_parser('check', help='Data consistency checks only (not semantic Gold verification)')
    p.set_defaults(func=check)
    p = sub.add_parser('prepare')
    p.add_argument('--world', required=True, choices=['R0','R1_L','R1_H','R2_L','R2_H','R3_L','R3_H'])
    p.add_argument('--run-id', required=True)
    p.add_argument('--model', required=True)
    p.add_argument('--model-version', default='')
    p.add_argument('--settings', default='')
    p.set_defaults(func=prepare)
    p = sub.add_parser('record')
    p.add_argument('--run', required=True)
    p.add_argument('--stage', required=True, choices=STAGES)
    p.add_argument('--response', required=True)
    p.set_defaults(func=record)
    p = sub.add_parser('report-failure', help='Manually record confirmed technical failure (new run ID required to retry)')
    p.add_argument('--run', required=True)
    p.add_argument('--stage', required=True, choices=STAGES)
    p.add_argument('--reason', required=True, choices=sorted(TECHNICAL_FAILURES | MODEL_FORMAT_FAILURES))
    p.add_argument('--detail', default='')
    p.add_argument('--response', default='')
    p.set_defaults(func=report_failure)
    p = sub.add_parser('audit')
    p.add_argument('--run', required=True)
    p.set_defaults(func=audit)
    p = sub.add_parser('summary', help='Summarize completion, concluded-answer accuracy and paired quality by model/config')
    p.add_argument('--runs-root', default=None)
    p.add_argument('--output', default=None)
    p.set_defaults(func=summary_cmd)
    args = ap.parse_args()
    try:
        args.func(args)
    except Exception as exc:
        print(f'ERROR: {type(exc).__name__}: {exc}', file=sys.stderr)
        sys.exit(1)


if __name__ == '__main__':
    cli()
